            <p><?php esc_html_e( 'Documentación integrada de la versión independiente: guía de uso y referencia técnica. Consultarla no ejecuta auditorías ni modifica el catálogo.', 'taxocommerce-auditor' ); ?></p>
            <p><a href="#tca-manual-user"><?php esc_html_e( 'Manual de usuario', 'taxocommerce-auditor' ); ?></a> · <a href="#tca-manual-tech"><?php esc_html_e( 'Manual técnico', 'taxocommerce-auditor' ); ?></a></p>

            <div id="tca-manual-user">
                <h2><?php esc_html_e( '1. Manual de usuario', 'taxocommerce-auditor' ); ?></h2>
                <h3><?php esc_html_e( '1.1 Objetivo y acceso', 'taxocommerce-auditor' ); ?></h3>
                <p><?php esc_html_e( 'Auditor detecta incidencias de calidad editorial y estructura, propone prioridades de revisión y presenta informes.', 'taxocommerce-auditor' ); ?> <strong><?php esc_html_e( 'No corrige, publica, elimina, mueve ni redirige productos, categorías, entradas, páginas ni preguntas frecuentes.', 'taxocommerce-auditor' ); ?></strong> <?php esc_html_e( 'Su fuente principal es WordPress/WooCommerce; otros módulos aportan contexto local cuando está disponible.', 'taxocommerce-auditor' ); ?></p>
                <p><?php esc_html_e( 'Acceso: en el administrador de WordPress,', 'taxocommerce-auditor' ); ?> <strong><?php esc_html_e( 'TaxoCommerce Core → Auditor', 'taxocommerce-auditor' ); ?></strong> <?php esc_html_e( 'cuando Core está instalado, o menú propio', 'taxocommerce-auditor' ); ?> <strong><?php esc_html_e( 'Auditor', 'taxocommerce-auditor' ); ?></strong> <?php esc_html_e( 'en caso contrario. El administrador debe contar con permiso', 'taxocommerce-auditor' ); ?> <code>manage_options</code>.</p>
                <h3><?php esc_html_e( '1.2 Los cinco ámbitos', 'taxocommerce-auditor' ); ?></h3>
